SELECT 'report_metadata' section,datetime('now') generated_at_utc,datetime('now','-7 days') current_start_utc,datetime('now','-14 days') previous_start_utc,'UTC rolling weeks; MTD boundary supplied by Europe/Lisbon calendar' reporting_boundary;
SELECT 'weekly_sessions' section,CASE WHEN created_at>=datetime('now','-7 days') THEN 'last7' ELSE 'previous7' END period,COUNT(DISTINCT session_id) sessions,MIN(created_at) first_event,MAX(created_at) last_event FROM traffic_guard_events WHERE decision='allowed' AND created_at>=datetime('now','-14 days') GROUP BY period;
SELECT 'mtd_sessions' section,COUNT(DISTINCT session_id) sessions,ROUND(COUNT(DISTINCT session_id)*1.0/CAST('{{formatDate(now; "D"; "Europe/Lisbon")}}' AS INTEGER),2) daily_average_calendar_days_including_today,MIN(created_at) first_event,MAX(created_at) last_event FROM traffic_guard_events WHERE decision='allowed' AND created_at>='{{formatDate(parseDate(formatDate(now; "YYYY-MM-01"; "Europe/Lisbon"); "YYYY-MM-DD"; "Europe/Lisbon"); "YYYY-MM-DD HH:mm:ss"; "UTC")}}';
SELECT 'guard_decisions' section,decision,reason,COUNT(*) events FROM traffic_guard_events WHERE created_at>=datetime('now','-14 days') GROUP BY decision,reason;
SELECT 'daily_sessions' section,date(created_at) day,COUNT(DISTINCT session_id) sessions FROM traffic_guard_events WHERE decision='allowed' AND created_at>=datetime('now','-30 days') GROUP BY day;
SELECT 'verified_outbound' section,CASE WHEN created_at>=datetime('now','-7 days') THEN 'last7' ELSE 'previous7' END period,COUNT(*) outbound,COALESCE(SUM(affiliate_active_at_click),0) monetized_outbound,COUNT(DISTINCT session_id) outbound_sessions FROM verified_outbound_events WHERE created_at>=datetime('now','-14 days') GROUP BY period;
SELECT 'outbound_demand' section,tool_slug,COUNT(*) outbound,COALESCE(SUM(affiliate_active_at_click),0) monetized_outbound FROM verified_outbound_events WHERE created_at>=datetime('now','-30 days') GROUP BY tool_slug ORDER BY outbound DESC;
SELECT 'tracking_metadata' section,key,value FROM outbound_integrity_meta UNION ALL SELECT 'visitor_metadata',key,value FROM visitor_tracking_meta;
SELECT 'engine_run_summary' section,engine,status,COUNT(*) runs,MAX(completed_at) latest_completion FROM engine_runs WHERE started_at>=datetime('now','-7 days') GROUP BY engine,status;
SELECT 'engine_runs' section,* FROM engine_runs WHERE started_at>=datetime('now','-7 days') ORDER BY started_at DESC LIMIT 500;
SELECT 'external_evidence' section,* FROM external_engine_evidence WHERE observed_at>=datetime('now','-7 days') ORDER BY observed_at DESC LIMIT 500;
SELECT 'vendor_amplification_sent' section,tool_slug,COUNT(*) sent,MAX(outreach_sent_at) latest_sent FROM distribution_vendor_amplification WHERE outreach_sent_at>=datetime('now','-7 days') GROUP BY tool_slug;
SELECT 'distribution_event_totals' section,date(observed_at) day,surface_slug,event_type,status,COUNT(*) events,MIN(observed_at) first_at,MAX(observed_at) last_at FROM distribution_events WHERE datetime(observed_at)>=datetime('now','-7 days') GROUP BY day,surface_slug,event_type,status;
SELECT 'distribution_events' section,* FROM distribution_events WHERE datetime(observed_at)>=datetime('now','-7 days') ORDER BY observed_at DESC LIMIT 500;
SELECT 'ledger_limit' section,'distribution_events' table_name,COUNT(*) total_rows,500 detail_limit FROM distribution_events WHERE datetime(observed_at)>=datetime('now','-7 days');
SELECT 'distribution_submissions' section,submission_id,surface_slug,asset_url,status,attempts,last_attempt_at,submitted_at,response_url,error,human_required,updated_at FROM distribution_submissions WHERE updated_at>=datetime('now','-7 days') ORDER BY updated_at DESC LIMIT 500;
SELECT 'distribution_economics' section,* FROM distribution_economic_learning;
SELECT 'distribution_costs' section,* FROM distribution_surface_costs;
SELECT 'attributed_browser_sessions' section,source,COUNT(DISTINCT session_id) sessions FROM confirmed_visitor_events v WHERE created_at>=datetime('now','-7 days') AND EXISTS(SELECT 1 FROM traffic_guard_events g WHERE g.session_id=v.session_id AND g.decision='allowed') GROUP BY source;
SELECT 'vendor_confirmed_revenue' section,status,currency,COUNT(*) conversions,SUM(commission) commission FROM revenue_ledger WHERE status IN ('confirmed','paid') AND evidence_ref IS NOT NULL AND created_at>=datetime('now','-30 days') GROUP BY status,currency;
SELECT 'measurement_coverage' section,'traffic_guard_events' table_name,MIN(created_at) first_retained_event,MAX(created_at) last_retained_event,COUNT(*) retained_events FROM traffic_guard_events UNION ALL SELECT 'measurement_coverage','verified_outbound_events',MIN(created_at),MAX(created_at),COUNT(*) FROM verified_outbound_events;
SELECT 'outbound_tracking_coverage' section,* FROM outbound_integrity_meta;
